  <title>Football App</title>
</head>
<body>
  <h1>Football App</h1>
  <form id="team-form">
    <label for="team1">Team 1:</label>
    <input type="text" id="team1" name="team1" required>

    <label for="team2">Team 2:</label>
    <input type=text id="team2" name="team2" required>

    <button type="submit">Get Games</button>
  </form>

  <div id="games-container"></div>

  <script>
    document.getElementById('team-form').addEventListener('submit', async (event) => {
      event.preventDefault();

      const team1 = document.getElementById('team1').value;
      const team2 = document.getElementById('team2').value;

      const response = await fetch(`/games/${team1}/${team2}`);
      const games = await response.json();

      const gamesContainer = document.getElementById('games-container');
      gamesContainer.innerHTML = '';

      games.forEach((game) => {
        const gameElement = document.createElement('div');
        gameElement.innerHTML = `
          <h3>${game.match.date} - ${game.match.location}</h3>
          <p>${game.match.homeTeam.name} ${game.match.score.homeTeam} - ${game.match.score.awayTeam} ${game.match.awayTeam.name}</p>
        `;
        gamesContainer.appendChild(gameElement);
      });
    });
  </script>
</body>
</html>

// 4. Display the last games between the selected teams

// Run the server
node server.js

// Open your browser and go to http://localhost:3000
```

